"use client";
import { matchesSearch } from "@/lib/search";
import { buyerDisplayCopy } from "@/lib/buyer-display-copy";
import { useState } from "react";
import Link from "next/link";
import inventory from "@/lib/market-view-data";
import { RoadmarkLogo } from "./roadmark-logo";
const labels: Record<string, string> = {
  accepting_orders: "Accepting orders · advertised",
  accepting_order_requests_advertised:
    "Order requests advertised · confirm acceptance",
  preorder: "Pre-order",
  listed_unconfirmed: "Listed · ordering unconfirmed",
  not_current: "Not verified as current",
  unverified: "Stock not verified",
  new_stock_listed: "New stock advertised · confirm exact vehicle",
  verified_new_stock: "Specific new stock verified",
};
export default function MarketAudit() {
  const [q, setQ] = useState(""),
    [status, setStatus] = useState("all"),
    [vehicleClass, setVehicleClass] = useState("all"),
    [limit, setLimit] = useState(24);
  const typedRecords =
    inventory.records as ((typeof inventory.records)[number] & {
      vehicleClass?: string;
    })[];
  const classLabels: Record<string, string> = {
    passenger: "Cars, SUVs & people movers",
    van: "Vans",
    ute: "Utes",
    truck: "Trucks",
    bus: "Buses",
    motorcycle: "Motorcycles & scooters",
    other: "Other / class to verify",
  };
  const records = typedRecords.filter(
    (r) =>
      matchesSearch(
        [r.brand, r.model, ...r.trims, ...(r.aliases ?? []), ...(r.modelAliases ?? [])].join(" "),
        q,
      ) &&
      (status === "all" || r.orderStatus === status) &&
      (vehicleClass === "all" || (r.vehicleClass || "other") === vehicleClass),
  );
  return (
    <main id="main" className="roadmark-discovery market-audit">
      <header className="container discovery-hero">
        <RoadmarkLogo />
        <p className="eyebrow">The market, with the gaps visible.</p>
        <h1>
          More choice.
          <br />
          <span>Less guesswork.</span>
        </h1>
        <p className="lede">
          A growing Australian new-EV audit beyond the original ten-family
          shortlist. A listing, an open order book and a car on a dealer’s
          forecourt are three different things.
        </p>
        <p className="discovery-scope">
          Checked {inventory.checkedAt} · {inventory.records.length} additional
          model records · Audit incomplete
        </p>
        <p className="small muted">
          Audit counts include uncertain, future-delivery and withdrawn
          listings. They are not a count of vehicles available to buy today.
          Motorcycles and scooters with cited supplier road-use claims are included; their full
          market coverage and specialist imports remain open.
        </p>
        <Link href="/">← Discover researched strengths</Link>
      </header>
      <section className="container discovery-content">
        <div className="market-filters">
          <label>
            Search the wider market
            <input
              type="search"
              value={q}
              onChange={(e) => {
                setQ(e.target.value);
                setLimit(24);
              }}
              placeholder="Brand, model or trim"
            />
          </label>
          <label>
            Vehicle type
            <select
              value={vehicleClass}
              onChange={(e) => {
                setVehicleClass(e.target.value);
                setLimit(24);
              }}
            >
              <option value="all">All vehicle types</option>
              {[...new Set(typedRecords.map((r) => r.vehicleClass || "other"))]
                .sort()
                .map((key) => (
                  <option key={key} value={key}>
                    {classLabels[key] || key}
                  </option>
                ))}
            </select>
          </label>
          <label>
            Order evidence
            <select
              value={status}
              onChange={(e) => {
                setStatus(e.target.value);
                setLimit(24);
              }}
            >
              <option value="all">All evidence states</option>
              {Object.entries(inventory.statusDefinitions).map(([key]) => (
                <option key={key} value={key}>
                  {labels[key]}
                </option>
              ))}
            </select>
          </label>
        </div>
        <p role="status">
          {records.length} model records. Exact-trim fact coverage varies;
          unverified measurements stay out of rankings.
        </p>
        <div className="market-records">
          {records.slice(0, limit).map((r) => (
            <article key={r.id}>
              <div className="discovery-car-top">
                <p className="eyebrow">{r.brand}</p>
                <span className="small muted">Checked {r.checkedAt}</span>
              </div>
              <p className="small muted">
                {classLabels[r.vehicleClass || "other"]}
              </p>
              <h2>{r.model}</h2>
              <p className="market-status">
                <strong>{labels[r.orderStatus] || r.orderStatus}</strong>
                <span>
                  {labels[r.stockStatus] || r.stockStatus.replaceAll("_", " ")}
                </span>
              </p>
              <h3>Named Australian configurations</h3>
              {r.trims.length ? (
                <ul>
                  {r.trims.map((t) => (
                    <li key={t}>{t}</li>
                  ))}
                </ul>
              ) : (
                <p>Exact trim names still need verification.</p>
              )}
              <p className="small muted">
                {r.trimCoverage.replaceAll("_", " ")}
              </p>
              <p>{buyerDisplayCopy(r.id, "evidenceNote", r.evidenceNote)}</p>
              <details>
                <summary>Evidence & limitations</summary>
                <ul>
                  {r.sourceUrls.map((u, i) => (
                    <li key={u}>
                      <a href={u} target="_blank" rel="noreferrer">
                        Source {i + 1} · {new URL(u).hostname} ↗
                      </a>
                    </li>
                  ))}
                </ul>
                <ul>
                  {r.limitations.map((l, i) => (
                    <li key={i}>{buyerDisplayCopy(r.id, `limitations[${i}]`, l)}</li>
                  ))}
                </ul>
              </details>
            </article>
          ))}
        </div>
        {!records.length && (
          <div className="discovery-empty">
            <h2>No matching audited records</h2>
            <p>
              This audit is incomplete; an empty result does not establish that
              a vehicle is unavailable.
            </p>
            <button
              className="button"
              onClick={() => {
                setQ("");
                setStatus("all");
                setVehicleClass("all");
                setLimit(24);
              }}
            >
              Clear filters
            </button>
          </div>
        )}
        {records.length > limit && (
          <div className="discovery-more">
            <p>
              Showing {limit} of {records.length} matching model records.
              Filters search the whole audit.
            </p>
            <button className="button" onClick={() => setLimit(limit + 24)}>
              Show 24 more records
            </button>
          </div>
        )}
        <section className="market-method">
          <h2>What this audit does and doesn’t establish</h2>
          <p>{inventory.scope}</p>
          <ul>
            {inventory.notes.map((n) => (
              <li key={n}>{n}</li>
            ))}
          </ul>
          <p>
            The growing detailed catalogue is available in discovery.
            Market-audit records alone do not enter rankings until their
            exact-trim measurements, comparable bases and supporting evidence
            pass review.
          </p>
          <h3>Reading availability</h3>
          <dl>
            {Object.entries(inventory.statusDefinitions).map(([key, note]) => (
              <div key={key}>
                <dt>{labels[key]}</dt>
                <dd>{note}</dd>
              </div>
            ))}
          </dl>
        </section>
      </section>
    </main>
  );
}

import { fixture100, reconstructMarketBeforeCheckpoint100, sourceBeforeCheckpoint100 } from "./checkpoint100-market-history";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import type { Car, Research } from "../../src/lib/types";

const hash = (v: unknown) => createHash("sha256").update(JSON.stringify(v)).digest("hex");
const sha = (v: Uint8Array) => createHash("sha256").update(v).digest("hex");
const fixtureBytes = readFileSync(new URL("../../qa/checkpoint99-mazda-fixture.json", import.meta.url));
assert.equal(sha(fixtureBytes), "405e14b6a02a771fba0fb8cdfea6f651c817f6b8e112dfb531dd94b73164e3a2", "Exact authored checkpoint99 fixture");
export const fixture99 = JSON.parse(fixtureBytes.toString("utf8"));
const f91 = JSON.parse(readFileSync(new URL("../../qa/checkpoint91/checkpoint91-runtime-fixture.json", import.meta.url), "utf8"));
const read = (file: string) => readFileSync(new URL("../../" + file, import.meta.url));
// Normalize only the whole-hash-exact100 inventory before retaining every existing99 pin.
const atCheckpoint99 = (file: string, current: Uint8Array): Buffer =>
  file === fixture100.marketFile && sha(current) === fixture100.afterSHA256
    ? sourceBeforeCheckpoint100(file, current)
    : Buffer.from(current);

type FileSpec = { beforeSHA256: string; afterSHA256: string; beforeJSONSHA256: string; afterJSONSHA256: string; insertions?: { at: number; currentAt: number; text: string }[] };

/** Exact whole-input verification precedes reversal. Original number notation is retained. */
export function sourceBeforeCheckpoint99(file: string, current: Uint8Array): Buffer {
  current = atCheckpoint99(file, current);
  const spec = fixture99.files[file] as FileSpec | undefined;
  assert.ok(spec, `No checkpoint99 byte delta for ${file}`);
  assert.equal(sha(current), spec.afterSHA256, `Unapproved checkpoint99 source: ${file}`);
  let text = Buffer.from(current).toString("utf8");
  if (spec.insertions) {
    for (const insertion of [...spec.insertions].reverse()) {
      assert.equal(text.slice(insertion.currentAt, insertion.currentAt + insertion.text.length), insertion.text);
      text = text.slice(0, insertion.currentAt) + text.slice(insertion.currentAt + insertion.text.length);
    }
  } else {
    assert.equal(file, "data/market-inventory-2026-10-10.json");
    text = JSON.stringify(reconstructMarketBeforeCheckpoint99(JSON.parse(text)), null, 2) + "\n";
  }
  const bytes = Buffer.from(text);
  assert.equal(sha(bytes), spec.beforeSHA256, `Exact predecessor bytes: ${file}`);
  return bytes;
}
export function createCheckpoint99SourceReader(readCurrent: (file: string) => Buffer) {
  // Check the coordinated four-file state before exposing any predecessor.
  for (const [file, spec] of Object.entries(fixture99.files) as [string, FileSpec][])
    assert.equal(sha(atCheckpoint99(file, readCurrent(file))), spec.afterSHA256, `Unapproved checkpoint99 source: ${file}`);
  return (file: string): Buffer => Object.hasOwn(fixture99.files, file)
    ? sourceBeforeCheckpoint99(file, readCurrent(file))
    : Buffer.from(readCurrent(file));
}
export function dataBeforeCheckpoint99(file: string): Record<string, unknown> {
  const bytes = Object.hasOwn(fixture99.files, file) ? sourceBeforeCheckpoint99(file, read(file)) : read(file);
  return JSON.parse(bytes.toString("utf8"));
}
/** Only the exact revised Mazda row, context and one sidecar may be undone. */
export function reconstructMarketBeforeCheckpoint99<T>(value: T): T {
  if (hash(value) === fixture100.afterJSONSHA256) value = reconstructMarketBeforeCheckpoint100(value);
  const file = "data/market-inventory-2026-10-10.json";
  assert.equal(hash(value), fixture99.files[file].afterJSONSHA256, "Whole checkpoint99 market value");
  const market = structuredClone(value) as unknown as { records: unknown[]; sourceArtifacts: unknown[]; detailedCatalogueContext: unknown };
  assert.deepEqual(market.records[fixture99.market.index], fixture99.market.afterRow);
  assert.deepEqual(market.sourceArtifacts.at(-1), fixture99.market.appendedArtifact);
  assert.deepEqual(market.detailedCatalogueContext, fixture99.market.afterContext);
  market.records[fixture99.market.index] = structuredClone(fixture99.market.beforeRow);
  market.sourceArtifacts.pop();
  market.detailedCatalogueContext = structuredClone(fixture99.market.beforeContext);
  assert.equal(hash(market), fixture99.files[file].beforeJSONSHA256, "Whole unchanged checkpoint98 market predecessor");
  return market as T;
}
export function researchBeforeCheckpoint99(value: Research): Research {
  const d = structuredClone(value);
  for (const [key, rows] of Object.entries(fixture99.researchDelta) as [keyof Research, unknown[]][]) {
    const actual = d[key] as unknown[];
    assert.ok(Array.isArray(actual));
    assert.deepEqual(actual.slice(-rows.length), rows, `Exact appended research ${key}`);
    (d as unknown as Record<string, unknown>)[key] = actual.slice(0, -rows.length);
  }
  const sourceAt: number = fixture99.sourceInsertionIndex;
  const addedSources = fixture99.dataDelta.sources;
  assert.deepEqual(d.sources.slice(sourceAt, sourceAt + addedSources.length), addedSources, "Exact interior source block");
  d.sources.splice(sourceAt, addedSources.length);
  assert.deepEqual(d.metadata, { ...fixture99.previousMetadata, added_variant_count: fixture99.previousMetadata.added_variant_count + 2, added_feature_row_count: fixture99.previousMetadata.added_feature_row_count + 138 });
  d.metadata = structuredClone(fixture99.previousMetadata);
  assert.equal(hash(d), fixture99.previousResearchSHA256, "Complete original research, including every source and unknown");
  return d;
}
export function carsBeforeCheckpoint99(cars: Car[]): Car[] {
  assert.equal(cars.length, 345, "Current99 exact record count");
  assert.equal(new Set(cars.map(c => c.id)).size, 345);
  assert.deepEqual(JSON.parse(JSON.stringify(cars.slice(-2))), fixture99.expectedCars, "Both full authored Mazda cars, facts and summaries");
  const before = cars.slice(0, -2);
  assert.deepEqual(before.map(c => c.id), f91.previousCars.map((c: { id: string }) => c.id));
  for (const [i, c] of before.entries())
    assert.equal(hash(c), c.id === f91.targetId ? f91.approvedTargetSHA256 : f91.previousCars[i].hash, `Unchanged pre99 car: ${c.id}`);
  return structuredClone(before);
}
export function countsBeforeCheckpoint99(cars: Car[], data: Research) {
  const previousCars = carsBeforeCheckpoint99(cars), previousData = researchBeforeCheckpoint99(data);
  const counts = { variants: previousCars.length, families: new Set(previousCars.map(c => c.modelFamily || c.family)).size, generations: previousData.models.length, criteria: previousData.criteria.length, evidence: previousData.feature_evidence.length, current: previousCars.filter(c => c.availability === "current_or_order_listed").length, outgoing: previousCars.filter(c => c.availability === "outgoing").length, provisional: previousCars.filter(c => c.availability === "announced_provisional").length };
  assert.deepEqual(counts, fixture99.counts.before);
  return counts;
}

import { createCheckpoint101SourceReader } from "./checkpoint101-source-history";
import { createCheckpoint99SourceReader, researchBeforeCheckpoint99, carsBeforeCheckpoint99 } from "./checkpoint99-history";
import { createRequire } from "node:module";
import { createCheckpoint96SourceReader } from "./checkpoint96-source-history";
import { createCheckpoint97SourceReader } from "./checkpoint97-source-history";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";
import { catalogue, research } from "../../src/lib/data";
import { resolveBuyerProposal } from "../../src/lib/buyer-proposal-storage";
import type { SellingPointProposal } from "../../src/lib/selling-points";
import type { Car } from "../../src/lib/types";
const require = createRequire(import.meta.url);
const H = require("../../qa/checkpoint91/checkpoint91-harness.cjs");
const core = require("../../qa/checkpoint91/checkpoint91-history-core.cjs");
const dir = fileURLToPath(new URL("../../qa/checkpoint91/", import.meta.url));
const fixture = core.readRuntimeFixture(dir);
const f = H.loadFixtures(dir);
const readBefore99 = createCheckpoint99SourceReader((file) => readFileSync(new URL("../../" + file, import.meta.url)));
const read = (name: string) => JSON.parse(readBefore99(name).toString("utf8"));
// Verify97 first, then let the unchanged96 reader verify and recover its predecessors.
const readSourceBefore97 = createCheckpoint97SourceReader(createCheckpoint101SourceReader(readBefore99));
const readSourceBefore96 = createCheckpoint96SourceReader(readSourceBefore97);
// One input verification per test module instance; never accept post91 drift as a baseline.
for (const [file, pin] of Object.entries(f.pins) as [string, { sha256: string }][]) {
  if (file !== H.PROPOSAL_FILE && file !== H.LEDGER_FILE)
    assert.equal(H.sha(readSourceBefore96(file)), pin.sha256, file);
}
const previousStorage = H.freeze(core.previousStorage(read(H.PROPOSAL_FILE), read(H.LEDGER_FILE), fixture, f));
core.checkResearch(researchBeforeCheckpoint99(research()), fixture);
/** Verifies the complete approved+1 delta before any historical reconstruction. */
export function carsBeforeCheckpoint91(cars: Car[] = catalogue()): Car[] {
  return core.previousCars(carsBeforeCheckpoint99(cars), fixture) as Car[];
}
/** Removes only the exactly verified coordinated proposal+ledger append. */
export function dataBeforeCheckpoint91(file: string): Record<string, unknown> {
  if (file !== H.PROPOSAL_FILE && file !== H.LEDGER_FILE) return read(file);
  return structuredClone(file === H.PROPOSAL_FILE ? previousStorage.stored : previousStorage.ledger) as Record<string, unknown>;
}
/** Keep old policy-date counts on their exact historical proposal, never by changing328 to329. */
export function buyerProposalBeforeCheckpoint91(): SellingPointProposal {
  return resolveBuyerProposal(structuredClone(previousStorage.stored), structuredClone(previousStorage.ledger));
}

import { createCheckpoint101SourceReader } from "./helpers/checkpoint101-source-history";
import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { createCheckpoint97SourceReader } from "./helpers/checkpoint97-source-history";
import {
  createCheckpoint96SourceReader,
  sourceBeforeCheckpoint96,
} from "./helpers/checkpoint96-source-history";

const discovery = "src/components/discovery.tsx";
const portable = "src/portable/link.tsx";
const files = [discovery, portable];
const read = createCheckpoint97SourceReader(createCheckpoint101SourceReader((file) =>
  readFileSync(new URL("../" + file, import.meta.url)),
));
const sha = (bytes: Uint8Array) =>
  createHash("sha256").update(bytes).digest("hex");
const expected = [
  { sha256: "c382047506d1881d4483e6478757dca41fc6d8011855e151027df027f689aa6f", bytes: 26192 },
  { sha256: "0add93ac8b2209b4cba733f805d3bfb7f9252fd3d33bd0d9b3da65c95a8ecfe6", bytes: 647 },
];
function replaceOne(source: string, from: string, to: string) {
  assert.equal(source.split(from).length, 2, from);
  return Buffer.from(source.replace(from, to));
}

test("approved96 sources reconstruct exact checkpoint95 bytes and the original91 Discovery pin", () => {
  for (const [index, file] of files.entries()) {
    const current = read(file);
    const original = Buffer.from(current);
    const previous = sourceBeforeCheckpoint96(file, current);
    assert.equal(sha(previous), expected[index].sha256);
    assert.equal(previous.length, expected[index].bytes);
    assert.notEqual(sha(previous), sha(current));
    assert.deepEqual(current, original, "reconstruction must not mutate its input");
  }
  const pins = JSON.parse(read("qa/checkpoint91/before-app-input-hashes.json").toString());
  assert.equal(pins[discovery].sha256, expected[0].sha256);
  assert.equal(pins[portable], undefined, "portable is validated in addition to the original91 pins");
});

test("source reconstruction rejects already-old, swapped, truncated, trailing and line-ending mutations", () => {
  for (const [index, file] of files.entries()) {
    const current = read(file);
    const old = sourceBeforeCheckpoint96(file, current);
    const mutations = [
      old,
      read(files[1 - index]),
      current.subarray(0, current.length - 1),
      Buffer.concat([current, Buffer.from("\n")]),
      Buffer.from(current.toString().replaceAll("\n", "\r\n")),
      Buffer.concat([Buffer.from("// unrelated change\n"), current]),
    ];
    for (const mutation of mutations)
      assert.throws(
        () => sourceBeforeCheckpoint96(file, mutation),
        /Unapproved checkpoint96 source/,
      );
  }
});

test("each Discovery prefetch false must remain present and false", () => {
  const source = read(discovery).toString();
  const marker = "prefetch={false}";
  const positions: number[] = [];
  for (let at = source.indexOf(marker); at !== -1; at = source.indexOf(marker, at + marker.length))
    positions.push(at);
  assert.equal(positions.length, 4);
  for (const at of positions) {
    for (const replacement of ["", "prefetch={true}"]) {
      const mutation = Buffer.from(
        source.slice(0, at) + replacement + source.slice(at + marker.length),
      );
      assert.throws(
        () => sourceBeforeCheckpoint96(discovery, mutation),
        /Unapproved checkpoint96 source/,
      );
    }
  }
});

test("Discovery route, evidence and unrelated prefetch mutations cannot masquerade as the reviewed delta", () => {
  const source = read(discovery).toString();
  const mutations = [
    replaceOne(source, "`/cars/${c.family}/${c.slug}`", "`/cars/changed/${c.family}/${c.slug}`"),
    replaceOne(source, "Evidence expires after 30 days.", "Evidence expires after 90 days."),
    replaceOne(source, '<Link href="/market">', '<Link href="/market" prefetch={false}>'),
  ];
  for (const mutation of mutations)
    assert.throws(
      () => sourceBeforeCheckpoint96(discovery, mutation),
      /Unapproved checkpoint96 source/,
    );
});

test("portable consumption and existing click-handler mutations are rejected", () => {
  const source = read(portable).toString();
  const mutations = [
    replaceOne(source, "  prefetch,\n", ""),
    replaceOne(source, "  void prefetch;\n", ""),
    replaceOne(source, "href={localUrl(href)}", "href={href}"),
    replaceOne(source, "        navigate(href);", "        navigate(\"/\");"),
    replaceOne(source, "          event.defaultPrevented ||\n", ""),
    replaceOne(source, "event.button !== 0", "event.button !== 1"),
    ...["metaKey", "ctrlKey", "shiftKey", "altKey"].map((key) =>
      replaceOne(source, `          event.${key} ||\n`, ""),
    ),
  ];
  for (const mutation of mutations)
    assert.throws(
      () => sourceBeforeCheckpoint96(portable, mutation),
      /Unapproved checkpoint96 source/,
    );
});

test("the historical reader rejects mixed approved and predecessor pairs", () => {
  const current = files.map(read);
  const previous = files.map((file, index) => sourceBeforeCheckpoint96(file, current[index]));
  for (const oldIndexes of [[0], [1], [0, 1]]) {
    assert.throws(
      () => createCheckpoint96SourceReader((file) => {
        const index = files.indexOf(file);
        assert.ok(index >= 0);
        return oldIndexes.includes(index) ? previous[index] : current[index];
      }),
      /Unapproved checkpoint96 source/,
    );
  }
});

test("both approved files are verified before the reader can serve a historical source", () => {
  const reads: string[] = [];
  const reader = createCheckpoint96SourceReader((file) => {
    reads.push(file);
    return read(file);
  });
  assert.deepEqual(reads, files);
  assert.equal(sha(reader(discovery)), expected[0].sha256);
  assert.throws(
    () => createCheckpoint96SourceReader((file) =>
      file === portable ? Buffer.concat([read(file), Buffer.from(" ")]) : read(file),
    ),
    /Unapproved checkpoint96 source: src\/portable\/link.tsx/,
  );
});

test("non-target sources stay raw and retain the original outer pin rejection", () => {
  const other = "src/lib/discovery.ts";
  const current = read(other);
  const pins = JSON.parse(read("qa/checkpoint91/before-app-input-hashes.json").toString());
  const reader = createCheckpoint96SourceReader(read);
  assert.deepEqual(reader(other), current);
  assert.equal(sha(reader(other)), pins[other].sha256);
  const mutation = Buffer.concat([current, Buffer.from("\n// unapproved drift\n")]);
  const changedReader = createCheckpoint96SourceReader((file) =>
    file === other ? mutation : read(file),
  );
  assert.deepEqual(changedReader(other), mutation);
  assert.throws(() => assert.equal(sha(changedReader(other)), pins[other].sha256));
  for (const file of ["./" + discovery, "/" + discovery, other])
    assert.throws(
      () => sourceBeforeCheckpoint96(file, read(discovery)),
      /No checkpoint96 source delta/,
    );
});

test("historical reader results cannot mutate cached predecessor bytes", () => {
  const reader = createCheckpoint96SourceReader(read);
  for (const [index, file] of files.entries()) {
    const first = reader(file);
    first.fill(0);
    const second = reader(file);
    assert.notStrictEqual(first, second);
    assert.equal(sha(second), expected[index].sha256);
    assert.equal(second.length, expected[index].bytes);
  }
});

test("checkpoint91 keeps its sealed fixture and original pin comparison through the verified reader", () => {
  assert.equal(
    sha(read("qa/checkpoint91/before-app-input-hashes.json")),
    "7e164c30217b8eff2180c1cdaefccea9effa95a2c9cce283cec01dfbe5768fb9",
  );
  const source = read("tests/helpers/checkpoint91-history.ts").toString();
  assert.ok(source.includes("const readBefore99 = createCheckpoint99SourceReader((file) => readFileSync(new URL(\"../../\" + file, import.meta.url)));"));
  assert.ok(source.includes("const readSourceBefore97 = createCheckpoint97SourceReader(readBefore99);"));
  assert.match(source, /const readSourceBefore96 = createCheckpoint96SourceReader\(readSourceBefore97\);/);
